 try{if(!native?.native&&localStorage.getItem(RUN_KEY)!==runId)return;localStorage.setItem(SAVE_KEY,value);localOK=true}catch{}
 if(native?.native)native.writeSave(value).catch(()=>toast('Não foi possível gravar o save nativo. Exporte um backup.'));
